coachView.changeJsFunction:
var container = this.context.element.querySelector(".multiselect-container");
var selectedItemsDiv = container.querySelector(".multiselect-selected-items");
var optionsContainer = container.querySelector(".multiselect-options");

// Get updated selected values
var selectedValues = this.getData() || [];
if (!Array.isArray(selectedValues)) {
  selectedValues = [];
}

// Get configuration
var options = this.getOption("options") || [];
var disabled = this.getOption("disabled");

// Update internal state
var state = {
  selectedValues: selectedValues,
  allOptions: options
};

// Re-render selected items
function renderSelectedItems() {
  // Clear existing tags
  var existingTags = selectedItemsDiv.querySelectorAll(".multiselect-tag");
  for (var i = 0; i < existingTags.length; i++) {
    selectedItemsDiv.removeChild(existingTags[i]);
  }

  var placeholderEl = selectedItemsDiv.querySelector(".multiselect-placeholder");

  if (state.selectedValues.length === 0) {
    if (placeholderEl) placeholderEl.style.display = "inline";
    return;
  }

  if (placeholderEl) placeholderEl.style.display = "none";

  state.selectedValues.forEach(function(value) {
    var option = state.allOptions.find(function(opt) {
      return opt.value === value;
    });

    if (!option) return;

    var tag = document.createElement("div");
    tag.className = "multiselect-tag";

    var tagText = document.createElement("span");
    tagText.className = "multiselect-tag-text";
    tagText.textContent = option.name;
    tag.appendChild(tagText);

    var removeBtn = document.createElement("button");
    removeBtn.type = "button";
    removeBtn.className = "multiselect-tag-remove";
    removeBtn.setAttribute("aria-label", "Remove " + option.name);
    removeBtn.innerHTML = '<svg viewBox="0 0 16 16" fill="currentColor"><path d="M12 4.7L11.3 4 8 7.3 4.7 4 4 4.7 7.3 8 4 11.3l.7.7L8 8.7l3.3 3.3.7-.7L8.7 8z"/></svg>';

    removeBtn.addEventListener("click", function(e) {
      e.stopPropagation();
      toggleOption(value);
    });

    tag.appendChild(removeBtn);
    selectedItemsDiv.appendChild(tag);
  });
}

// Toggle option selection
function toggleOption(value) {
  if (disabled) return;

  var index = state.selectedValues.indexOf(value);

  if (index !== -1) {
    state.selectedValues.splice(index, 1);
  } else {
    state.selectedValues.push(value);
  }

  this.setData(state.selectedValues);
  renderSelectedItems();
  updateOptions();
}

// Update options display
function updateOptions() {
  var optionElements = optionsContainer.querySelectorAll(".multiselect-option");

  optionElements.forEach(function(optionEl) {
    var value = optionEl.getAttribute("data-value");
    var isSelected = state.selectedValues.indexOf(value) !== -1;

    if (isSelected) {
      optionEl.classList.add("selected");
      optionEl.setAttribute("aria-selected", "true");
    } else {
      optionEl.classList.remove("selected");
      optionEl.setAttribute("aria-selected", "false");
    }
  });
}

// Execute updates
renderSelectedItems();
updateOptions();

// Update ARIA label
var count = state.selectedValues.length;
var label = count === 0 ? "No items selected" :
            count === 1 ? "1 item selected" :
            count + " items selected";
var inputWrapper = container.querySelector(".multiselect-input-wrapper");
if (inputWrapper) {
  inputWrapper.setAttribute("aria-label", label);
}

// Made with Bob

inlineScript.scriptBlock:
  // Store widget context reference
  var widget = this;


  var container = widget.context.element.querySelector(".multiselect-container");
  var wrapper = container.querySelector(".multiselect-wrapper");
  var inputWrapper = container.querySelector(".multiselect-input-wrapper");
  var selectedItemsDiv = container.querySelector(".multiselect-selected-items");
  var toggleBtn = container.querySelector(".multiselect-toggle");
  var dropdown = container.querySelector(".multiselect-dropdown");
  var searchInput = container.querySelector(".multiselect-search");
  var optionsContainer = container.querySelector(".multiselect-options");
  var selectAllBtn = container.querySelector(".multiselect-select-all");
  var clearAllBtn = container.querySelector(".multiselect-clear-all");
  var helperText = container.querySelector(".multiselect-helper-text");

  // Get configuration options
  var options = widget.getOption("options").items;;
  var placeholder = widget.getOption("placeholder") || "Select items...";
  var maxSelections = widget.getOption("maxSelections") || null;
  var showSearch = widget.getOption("showSearch");
  var showActions = widget.getOption("showActions");
  var disabled = widget.getOption("disabled");
  var helperTextValue = widget.getOption("helperText") || "";

  // Validate and ensure options is an array
  if (!options || !Array.isArray(options)) {
    options = [];
  }

  // Set default values
  if (showSearch === undefined || showSearch === null) showSearch = true;
  if (showActions === undefined || showActions === null) showActions = true;
  if (disabled === undefined || disabled === null) disabled = false;

  // Get selected values from bound data
  var selectedValues = widget.getData() || [];
  if (!Array.isArray(selectedValues)) {
    selectedValues = [];
  }

  // State management
  var state = {
    isOpen: false,
    selectedValues: selectedValues,
    filteredOptions: options.slice(), // Create a copy
    allOptions: options.slice() // Create a copy
  };

  // Initialize widget
  function init() {
    // Set placeholder
    var placeholderEl = selectedItemsDiv.querySelector(".multiselect-placeholder");
    if (placeholderEl) {
      placeholderEl.textContent = placeholder;
    }

    // Set helper text
    if (helperTextValue) {
      helperText.textContent = helperTextValue;
    }

    // Hide/show search
    if (!showSearch) {
      var searchWrapper = container.querySelector(".multiselect-search-wrapper");
      if (searchWrapper) searchWrapper.style.display = "none";
    }

    // Hide/show actions
    if (!showActions) {
      var actionsDiv = container.querySelector(".multiselect-actions");
      if (actionsDiv) actionsDiv.style.display = "none";
    }

    // Set disabled state
    if (disabled) {
      container.classList.add("disabled");
      inputWrapper.setAttribute("aria-disabled", "true");
    }

    // Render options and selected items
    renderOptions();
    renderSelectedItems();
    updateActionButtons();

    // Attach event listeners
    attachEventListeners();
  }

  // Render options in dropdown
  function renderOptions() {
    optionsContainer.innerHTML = "";

    if (state.filteredOptions.length === 0) {
      var noResults = document.createElement("div");
      noResults.className = "multiselect-no-results";
      noResults.textContent = "No results found";
      optionsContainer.appendChild(noResults);
      return;
    }

    state.filteredOptions.forEach(function(option) {
      var optionEl = document.createElement("div");
      optionEl.className = "multiselect-option";
      optionEl.setAttribute("role", "option");
      optionEl.setAttribute("data-value", option.value);
      optionEl.setAttribute("tabindex", "0");

      var isSelected = state.selectedValues.indexOf(option.value) !== -1;
      if (isSelected) {
        optionEl.classList.add("selected");
        optionEl.setAttribute("aria-selected", "true");
      } else {
        optionEl.setAttribute("aria-selected", "false");
      }

      // Checkbox
      var checkbox = document.createElement("div");
      checkbox.className = "multiselect-checkbox";
      checkbox.innerHTML = '<svg viewBox="0 0 16 16" fill="currentColor"><path d="M6.5 11.7L3.3 8.5l.7-.7 2.5 2.5 5.2-5.2.7.7z"/></svg>';
      optionEl.appendChild(checkbox);

      // Text
      var text = document.createElement("span");
      text.className = "multiselect-option-text";
      text.textContent = option.name;
      optionEl.appendChild(text);

      // Click handler
      optionEl.addEventListener("click", function() {
        toggleOption(option.value);
      });

      // Keyboard handler
      optionEl.addEventListener("keydown", function(e) {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          toggleOption(option.value);
        }
      });

      optionsContainer.appendChild(optionEl);
    });
  }

  // Render selected items as tags
  function renderSelectedItems() {
    // Clear existing tags
    var existingTags = selectedItemsDiv.querySelectorAll(".multiselect-tag");
    for (var i = 0; i < existingTags.length; i++) {
      selectedItemsDiv.removeChild(existingTags[i]);
    }

    var placeholderEl = selectedItemsDiv.querySelector(".multiselect-placeholder");

    if (state.selectedValues.length === 0) {
      if (placeholderEl) placeholderEl.style.display = "inline";
      return;
    }

    if (placeholderEl) placeholderEl.style.display = "none";

    state.selectedValues.forEach(function(value) {
      var option = state.allOptions.find(function(opt) {
        return opt.value === value;
      });

      if (!option) return;

      var tag = document.createElement("div");
      tag.className = "multiselect-tag";

      var tagText = document.createElement("span");
      tagText.className = "multiselect-tag-text";
      tagText.textContent = option.name;
      tag.appendChild(tagText);

      var removeBtn = document.createElement("button");
      removeBtn.type = "button";
      removeBtn.className = "multiselect-tag-remove";
      removeBtn.setAttribute("aria-label", "Remove " + option.name);
      removeBtn.innerHTML = '<svg viewBox="0 0 16 16" fill="currentColor"><path d="M12 4.7L11.3 4 8 7.3 4.7 4 4 4.7 7.3 8 4 11.3l.7.7L8 8.7l3.3 3.3.7-.7L8.7 8z"/></svg>';

      removeBtn.addEventListener("click", function(e) {
        e.stopPropagation();
        toggleOption(value);
      });

      tag.appendChild(removeBtn);
      selectedItemsDiv.appendChild(tag);
    });
  }

  // Toggle option selection
  function toggleOption(value) {
    if (disabled) return;

    var index = state.selectedValues.indexOf(value);

    if (index !== -1) {
      // Deselect
      state.selectedValues.splice(index, 1);
    } else {
      // Select
      if (maxSelections && state.selectedValues.length >= maxSelections) {
        showError("Maximum " + maxSelections + " items can be selected");
        return;
      }
      state.selectedValues.push(value);
    }

    // Update data binding
    widget.setData(state.selectedValues);

    // Re-render
    renderOptions();
    renderSelectedItems();
    updateActionButtons();
    updateAriaLabel();
  }

  // Toggle dropdown
  function toggleDropdown() {
    if (disabled) return;

    state.isOpen = !state.isOpen;

    if (state.isOpen) {
      dropdown.classList.add("open");
      inputWrapper.classList.add("active");
      inputWrapper.setAttribute("aria-expanded", "true");
      if (showSearch) searchInput.focus();
    } else {
      dropdown.classList.remove("open");
      inputWrapper.classList.remove("active");
      inputWrapper.setAttribute("aria-expanded", "false");
      searchInput.value = "";
      state.filteredOptions = state.allOptions;
      renderOptions();
    }
  }

  // Filter options based on search
  function filterOptions(searchTerm) {
    var term = searchTerm.toLowerCase().trim();

    if (!term) {
      state.filteredOptions = state.allOptions;
    } else {
      state.filteredOptions = state.allOptions.filter(function(option) {
        return option.name.toLowerCase().indexOf(term) !== -1 ||
               option.value.toLowerCase().indexOf(term) !== -1;
      });
    }

    renderOptions();
  }

  // Select all options
  function selectAll() {
    if (disabled) return;

    if (maxSelections) {
      state.selectedValues = state.allOptions.slice(0, maxSelections).map(function(opt) {
        return opt.value;
      });
      if (state.allOptions.length > maxSelections) {
        showError("Only first " + maxSelections + " items selected (limit reached)");
      }
    } else {
      state.selectedValues = state.allOptions.map(function(opt) {
        return opt.value;
      });
    }

    widget.setData(state.selectedValues);
    renderOptions();
    renderSelectedItems();
    updateActionButtons();
    updateAriaLabel();
  }

  // Clear all selections
  function clearAll() {
    if (disabled) return;

    state.selectedValues = [];
    widget.setData(state.selectedValues);
    renderOptions();
    renderSelectedItems();
    updateActionButtons();
    updateAriaLabel();
  }

  // Update action buttons state
  function updateActionButtons() {
    if (!showActions) return;

    if (state.selectedValues.length === 0) {
      clearAllBtn.disabled = true;
    } else {
      clearAllBtn.disabled = false;
    }

    if (maxSelections && state.selectedValues.length >= maxSelections) {
      selectAllBtn.disabled = true;
    } else if (state.selectedValues.length === state.allOptions.length) {
      selectAllBtn.disabled = true;
    } else {
      selectAllBtn.disabled = false;
    }
  }

  // Update ARIA label
  function updateAriaLabel() {
    var count = state.selectedValues.length;
    var label = count === 0 ? "No items selected" :
                count === 1 ? "1 item selected" :
                count + " items selected";
    inputWrapper.setAttribute("aria-label", label);
  }

  // Show error message
  function showError(message) {
    container.classList.add("error");
    helperText.textContent = message;
    helperText.classList.add("error");

    setTimeout(function() {
      container.classList.remove("error");
      helperText.textContent = helperTextValue;
      helperText.classList.remove("error");
    }, 3000);
  }

  // Attach event listeners
  function attachEventListeners() {
    // Toggle dropdown
    inputWrapper.addEventListener("click", toggleDropdown);
    toggleBtn.addEventListener("click", function(e) {
      e.stopPropagation();
      toggleDropdown();
    });

    // Search input
    if (showSearch) {
      searchInput.addEventListener("input", function(e) {
        filterOptions(e.target.value);
      });

      searchInput.addEventListener("click", function(e) {
        e.stopPropagation();
      });
    }

    // Action buttons
    if (showActions) {
      selectAllBtn.addEventListener("click", selectAll);
      clearAllBtn.addEventListener("click", clearAll);
    }

    // Close dropdown when clicking outside
    document.addEventListener("click", function(e) {
      if (!container.contains(e.target) && state.isOpen) {
        toggleDropdown();
      }
    });

    // Keyboard navigation
    inputWrapper.addEventListener("keydown", function(e) {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        toggleDropdown();
      } else if (e.key === "Escape" && state.isOpen) {
        toggleDropdown();
      }
    });
  }

  // Initialize the widget
  init();
  updateAriaLabel();
// Made with Bob

/* MultiSelect Widget - Modern Carbon Design System v11 */

.multiselect-container {
  width: 100%;
  font-family: 'IBM Plex Sans', 'Helvetica Neue', Arial, sans-serif; /* @bpm-font-family-sans-serif */
  font-size: 14px; /* @bpm-font-size-base */
  position: relative;
}

.multiselect-wrapper {
  position: relative;
  width: 100%;
}

/* Input Wrapper - Clean flat design */
.multiselect-input-wrapper {
  display: flex;
  align-items: center;
  min-height: 40px;
  padding: 0 12px;
  background-color: #f4f4f4; /* Gray 10 */
  border: none;
  border-bottom: 1px solid #8d8d8d; /* Gray 50 */
  cursor: pointer;
  transition: all 70ms cubic-bezier(0.2, 0, 0.38, 0.9);
  position: relative;
}

.multiselect-input-wrapper:hover {
  background-color: #e8e8e8; /* Gray 20 hover */
}

.multiselect-input-wrapper:focus-within,
.multiselect-input-wrapper.active {
  background-color: #ffffff; /* @bpm-body-bg */
  border-bottom: 2px solid #0f62fe; /* @bpm-color-primary */
  outline: 2px solid #0f62fe; /* @bpm-color-primary */
  outline-offset: -2px;
}

/* Selected Items Display */
.multiselect-selected-items {
  flex: 1;
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
  padding: 0.25rem 0;
  min-height: 32px;
  align-items: center;
}

.multiselect-placeholder {
  color: #6f6f6f;
  font-size: 1rem;
  line-height: 1.5;
}

/* Selected Item Tag - Modern pill design */
.multiselect-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 0 8px;
  height: 24px;
  background-color: #e0e0e0; /* Gray 20 */
  border-radius: 12px;
  font-size: 12px; /* @bpm-font-size-small */
  font-weight: 400; /* @bpm-font-weight-normal */
  line-height: 1;
  color: #161616; /* @bpm-text-color */
  max-width: 200px;
  transition: background-color 70ms cubic-bezier(0.2, 0, 0.38, 0.9);
  animation: tagSlideIn 0.2s ease-out;
}

.multiselect-tag:hover {
  background-color: #c6c6c6; /* Gray 30 */
}

@keyframes tagSlideIn {
  from {
    opacity: 0;
    transform: scale(0.8) translateY(-4px);
  }
  to {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

.multiselect-tag-text {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.multiselect-tag-remove {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  padding: 0;
  background: transparent;
  border: none;
  border-radius: 50%;
  cursor: pointer;
  color: #525252; /* Gray 70 */
  transition: all 70ms cubic-bezier(0.2, 0, 0.38, 0.9);
}

.multiselect-tag-remove:hover {
  background-color: #8d8d8d; /* Gray 50 */
  color: #ffffff; /* @bpm-body-bg */
}

.multiselect-tag-remove svg {
  width: 12px;
  height: 12px;
}

/* Toggle Button - Minimal design */
.multiselect-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  padding: 0;
  background: transparent;
  border: none;
  cursor: pointer;
  color: #161616; /* @bpm-text-color */
  transition: transform 110ms cubic-bezier(0.2, 0, 0.38, 0.9);
}

.multiselect-toggle:hover {
  background-color: #e0e0e0; /* Gray 20 */
}

.multiselect-input-wrapper.active .multiselect-toggle {
  transform: rotate(180deg);
}

.multiselect-icon {
  width: 16px;
  height: 16px;
}

/* Dropdown - Clean shadow */
.multiselect-dropdown {
  position: absolute;
  top: calc(100% + 1px);
  left: 0;
  right: 0;
  background-color: #ffffff; /* @bpm-body-bg */
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.3);
  z-index: 9000;
  max-height: 0;
  overflow: hidden;
  opacity: 0;
  transform: translateY(-4px);
  transition: all 110ms cubic-bezier(0.2, 0, 0.38, 0.9);
}

.multiselect-dropdown.open {
  max-height: 400px;
  opacity: 1;
  transform: translateY(0);
  overflow: visible;
}

/* Search Wrapper - Flat design */
.multiselect-search-wrapper {
  position: relative;
  padding: 8px;
  border-bottom: 1px solid #e0e0e0; /* Gray 20 */
  background-color: #ffffff; /* @bpm-body-bg */
}

.multiselect-search {
  width: 100%;
  height: 40px;
  padding: 0 40px 0 40px;
  background-color: #f4f4f4; /* Gray 10 */
  border: none;
  border-bottom: 1px solid #8d8d8d; /* Gray 50 */
  font-size: 14px; /* @bpm-font-size-base */
  font-family: inherit;
  line-height: 1.29;
  color: #161616; /* @bpm-text-color */
  transition: all 70ms cubic-bezier(0.2, 0, 0.38, 0.9);
}

.multiselect-search:hover {
  background-color: #e8e8e8; /* Gray 20 hover */
}

.multiselect-search:focus {
  background-color: #ffffff; /* @bpm-body-bg */
  border-bottom: 2px solid #0f62fe; /* @bpm-color-primary */
  outline: 2px solid #0f62fe; /* @bpm-color-primary */
  outline-offset: -2px;
}

.multiselect-search::placeholder {
  color: #6f6f6f;
}

.multiselect-search-icon {
  position: absolute;
  left: 16px;
  top: 50%;
  transform: translateY(-50%);
  width: 16px;
  height: 16px;
  color: #161616; /* @bpm-text-color */
  pointer-events: none;
}

/* Options List */
.multiselect-options {
  max-height: 240px;
  overflow-y: auto;
  padding: 0.25rem 0;
}

.multiselect-options::-webkit-scrollbar {
  width: 8px;
}

.multiselect-options::-webkit-scrollbar-track {
  background: #f4f4f4;
}

.multiselect-options::-webkit-scrollbar-thumb {
  background: #8d8d8d;
  border-radius: 4px;
}

.multiselect-options::-webkit-scrollbar-thumb:hover {
  background: #6f6f6f;
}

/* Option Item - Clean hover states */
.multiselect-option {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 11px 16px;
  cursor: pointer;
  font-size: 14px; /* @bpm-font-size-base */
  line-height: 1.29;
  color: #161616; /* @bpm-text-color */
  transition: background-color 70ms cubic-bezier(0.2, 0, 0.38, 0.9);
  position: relative;
}

.multiselect-option:hover {
  background-color: #e8e8e8; /* Gray 20 hover */
}

.multiselect-option.selected {
  background-color: #e0e0e0; /* Gray 20 */
}

.multiselect-option.selected:hover {
  background-color: #d0d0d0; /* Slightly darker on hover */
}

.multiselect-option.hidden {
  display: none;
}

/* Checkbox - Carbon style */
.multiselect-checkbox {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  border: 1px solid #8d8d8d; /* Gray 50 */
  background-color: transparent;
  transition: all 110ms cubic-bezier(0.2, 0, 0.38, 0.9);
  flex-shrink: 0;
  position: relative;
}

.multiselect-option:hover .multiselect-checkbox {
  border-color: #0f62fe; /* @bpm-color-primary */
}

.multiselect-option.selected .multiselect-checkbox {
  background-color: #0f62fe; /* @bpm-color-primary */
  border-color: #0f62fe; /* @bpm-color-primary */
}

.multiselect-checkbox svg {
  width: 12px;
  height: 12px;
  color: #ffffff; /* @bpm-body-bg */
  opacity: 0;
  transform: scale(0.5);
  transition: all 110ms cubic-bezier(0.2, 0, 0.38, 0.9);
}

.multiselect-option.selected .multiselect-checkbox svg {
  opacity: 1;
  transform: scale(1);
}

.multiselect-option-text {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Actions - Carbon button style */
.multiselect-actions {
  display: flex;
  gap: 1px;
  padding: 8px;
  border-top: 1px solid #e0e0e0; /* Gray 20 */
  background-color: #ffffff; /* @bpm-body-bg */
}

.multiselect-action-btn {
  flex: 1;
  height: 48px;
  padding: 0 16px;
  background-color: #0f62fe; /* @bpm-color-primary */
  border: none;
  color: #ffffff; /* @bpm-body-bg */
  font-size: 14px; /* @bpm-font-size-base */
  font-weight: 400; /* @bpm-font-weight-normal */
  cursor: pointer;
  transition: background-color 70ms cubic-bezier(0.2, 0, 0.38, 0.9);
}

.multiselect-action-btn:hover {
  background-color: #0353e9; /* @bpm-color-primary-dark */
}

.multiselect-action-btn:active {
  background-color: #002d9c; /* Darker blue */
}

.multiselect-action-btn:disabled {
  background-color: #c6c6c6; /* Gray 30 - @bpm-link-text-color-disabled */
  color: #8d8d8d; /* Gray 50 */
  cursor: not-allowed;
}

/* Helper Text */
.multiselect-helper-text {
  margin-top: 0.375rem;
  font-size: 0.875rem;
  line-height: 1.5;
  color: #6f6f6f;
}

.multiselect-helper-text.error {
  color: #da1e28;
}

/* Error State */
.multiselect-container.error .multiselect-input-wrapper {
  border-bottom-color: #da1e28;
}

.multiselect-container.error .multiselect-input-wrapper:focus-within {
  outline-color: #da1e28;
  border-bottom-color: #da1e28;
}

/* Disabled State */
.multiselect-container.disabled .multiselect-input-wrapper {
  background-color: #f4f4f4;
  border-bottom-color: transparent;
  cursor: not-allowed;
  opacity: 0.5;
}

.multiselect-container.disabled .multiselect-toggle {
  cursor: not-allowed;
}

/* No Results */
.multiselect-no-results {
  padding: 1.5rem;
  text-align: center;
  font-size: 1rem;
  color: #6f6f6f;
}

/* Responsive Design */
@media (max-width: 672px) {
  .multiselect-dropdown {
    max-height: 300px;
  }

  .multiselect-options {
    max-height: 180px;
  }

  .multiselect-tag {
    font-size: 0.875rem;
    max-width: 180px;
  }

  .multiselect-option {
    font-size: 0.9375rem;
  }
}

/* Accessibility */
.multiselect-option:focus {
  outline: 2px solid #0f62fe;
  outline-offset: -2px;
}

/* Animations */
@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(-8px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.multiselect-dropdown.open {
  animation: fadeIn 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

@keyframes pulse {
  0%, 100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.05);
  }
}

.multiselect-option:active {
  animation: pulse 0.3s ease;
}

/* Made with Bob */
